 TABLE(["Год","FCF, млрд ₽","Дисконт-фактор 18%","Приведённая стоимость"],[["1","148","0,847","125"],["2","157","0,718","113"],["3","166","0,609","101"],["Итого за 3 года","","","339"]],(3,3)),
